    /**
     * Handles loading a Customer using a UUID
     * @param		UUID uuid 
     * @return		Customer
     */    
    @GetMapping("/load")
    public Customer load( @RequestParam(required=true) UUID uuid ) {    	
    	Customer entity = null;

    	try {  
    		entity = service.getCustomer( new CustomerFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Customer using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Customer business objects
     * @return		Set<Customer>
     */
    @GetMapping("/")
    public List<Customer> loadAll() {                
    	List<Customer> customerList = null;
        
    	try {
            // load the Customer
            customerList = service.getAllCustomer();
            
            if ( customerList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Customers" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Customers ", exc );
        	return null;
        }

        return customerList;
                            
    }

